import timeit

def quadratisch(n):
    s = 0
    for i in range(n):
        for j in range(n):
            s += 1
    return s

for n in [500, 1000, 2000]:
    t = min(timeit.repeat(
        lambda: quadratisch(n),
        number=3, repeat=5)) / 3
    print(n, f"{t*1000:.1f} ms")

